        case .StartInProgress:
            writeInt(&buf, Int32(2))


        case .DifferentInstallation:
            writeInt(&buf, Int32(3))


        case .MissingInstallation:
            writeInt(&buf, Int32(4))


        case .InvalidInstallation:
            writeInt(&buf, Int32(5))


        case .ImportRequiresNewInstallation:
            writeInt(&buf, Int32(6))


        case .StaleImportReview:
            writeInt(&buf, Int32(7))


        case let .UnsupportedInstallation(version):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(version, into: &buf)


        case .InvalidPath:
            writeInt(&buf, Int32(9))


        case .StaleResetReview:
            writeInt(&buf, Int32(10))


        case let .CleanupPending(status):
            writeInt(&buf, Int32(11))
            FfiConverterTypeServiceRuntimeStatus.write(status, into: &buf)


        case let .ControllerKey(error):
            writeInt(&buf, Int32(12))
            FfiConverterTypeKeyError.write(error, into: &buf)


        case let .ManagementTargetKey(error):
            writeInt(&buf, Int32(13))
            FfiConverterTypeKeyError.write(error, into: &buf)


        case let .Connections(error):
            writeInt(&buf, Int32(14))
            FfiConverterTypeConnectionError.write(error, into: &buf)


        case let .Native(error):
            writeInt(&buf, Int32(15))
            FfiConverterTypeServiceRuntimeError.write(error, into: &buf)

